const TOOL_NAME = 'calculate';
const ALLOWED_OPERATIONS = ['add', 'subtract', 'multiply', 'divide'];
const ALLOWED_FIELDS = new Set(['a', 'b', 'operation']);

const toolSchema = {
  name: TOOL_NAME,
  description: 'Perform a basic arithmetic operation on two numbers.',
  inputSchema: {
    type: 'object',
    properties: {
      a: { type: 'number', description: 'First operand.' },
      b: { type: 'number', description: 'Second operand.' },
      operation: {
        type: 'string',
        enum: ALLOWED_OPERATIONS,
        description: 'Arithmetic operation to perform.',
      },
    },
    required: ['a', 'b', 'operation'],
    additionalProperties: false,
  },
};

export async function listTools() {
  return [toolSchema];
}

function ensureNumber(value, field) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new Error(`Field "${field}" must be a finite number.`);
  }
  return value;
}

function compute(a, b, operation) {
  switch (operation) {
    case 'add':
      return a + b;
    case 'subtract':
      return a - b;
    case 'multiply':
      return a * b;
    case 'divide':
      if (b === 0) throw new Error('Division by zero is not allowed.');
      return a / b;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object.');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_FIELDS.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  const a = ensureNumber(args.a, 'a');
  const b = ensureNumber(args.b, 'b');
  const operation = args.operation;
  if (typeof operation !== 'string' || !ALLOWED_OPERATIONS.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  const result = compute(a, b, operation);
  return { content: [{ type: 'text', text: String(result) }] };
}

