  try { await callTool('nope', {}); console.log('FAIL: unknown tool'); } catch (e) { console.log('OK unknown:', e.message); }
  // extra field
  try { await callTool('calculate', {a:1,b:2,operation:'add',c:3}); console.log('FAIL: extra field'); } catch (e) { console.log('OK extra:', e.message); }
  // missing field
  try { await callTool('calculate', {a:1,b:2}); console.log('FAIL: missing'); } catch (e) { console.log('OK missing:', e.message); }
  // unsupported operation
  try { await callTool('calculate', {a:1,b:2,operation:'mod'}); console.log('FAIL: unsup'); } catch (e) { console.log('OK unsup:', e.message); }
  // division by zero
  try { await callTool('calculate', {a:1,b:0,operation:'divide'}); console.log('FAIL: div0'); } catch (e) { console.log('OK div0:', e.message); }
  // non-numeric
  try { await callTool('calculate', {a:'1',b:2,operation:'add'}); console.log('FAIL: nonnum'); } catch (e) { console.log('OK nonnum:', e.message); }
  // happy paths
  console.log('add', (await callTool('calculate',{a:2,b:3,operation:'add'})).content[0].text);
